        # to create temporary instances on those subnets.
        member = "serviceAccount:restore-test-sa@liftit-bi.iam.gserviceaccount.com"
        role   = "roles/compute.networkUser"
      },
    ]
  }
}

resource "google_project_iam_member" "restore_test_cross_project" {
  for_each = {
    for idx, g in try(local.restore_test_cross_project[terraform.workspace], []) :
    "${g.role}-${g.member}" => g
  }
  project = local.project_id[terraform.workspace]
  role    = each.value.role
  member  = each.value.member
}

