#-----------------------------------------
# F2 — Cloud Run Job (Python restore-runner)
#-----------------------------------------
resource "google_cloud_run_v2_job" "restore_runner" {
  name     = "restore-runner"
  project  = local.project_id[terraform.workspace]
  location = local.region.principal

  labels = local.default_labels

  template {
    task_count  = 1
    parallelism = 1

    template {
      service_account = module.sa-permissions.service_account_email
      timeout         = "14400s" # 4 hours

      containers {
        image = local.runner_image

        resources {
          limits = {
            cpu    = "2"
            memory = "2Gi"
          }
        }

        env {
          name  = "WORKSPACE"
          value = terraform.workspace
        }
        env {
          name  = "PROJECT_ID"
          value = local.project_id[terraform.workspace]
        }
        env {
          name  = "REGION"
          value = local.region.principal
        }
        env {
          name  = "EVIDENCE_BUCKET"
          value = google_storage_bucket.evidence_v2.name
        }
        env {
          name  = "SLACK_SECRET_ID"
          value = local.slack_webhook_secret
        }
        env {
          name  = "KMS_SIGNING_KEY"
          value = local.kms_signing_key
        }
        env {
          name  = "MODE"
          value = "shadow"
        }
        env {
          name  = "PARALLELISM"
          value = tostring(local.runner_parallelism)
        }
      }

      vpc_access {
        connector = local.has_vpc_connector ? "projects/${local.vpc_connector_project}/locations/${local.region.principal}/connectors/serverless-connector" : null
        egress    = "PRIVATE_RANGES_ONLY"
      }
    }
  }

  lifecycle {
    ignore_changes = [
      # Image tag may be updated out of band by CI; ignore in TF
      template[0].template[0].containers[0].image,
    ]
  }
}

#-----------------------------------------
# F2 — Shadow scheduler (only staging in F2; rest paused)
#-----------------------------------------
resource "google_cloud_scheduler_job" "restore_runner_shadow" {
  name        = "restore-runner-shadow-trigger"
  description = "Triggers F2 restore-runner Cloud Run Job (shadow)"
  project     = local.project_id[terraform.workspace]
  region      = local.region.principal
  schedule    = "30 2 15 * *" # Day 15 02:30 BOG — 30 min after v1 staging
  time_zone   = "America/Bogota"
  paused      = terraform.workspace != "staging"

  http_target {
    http_method = "POST"
    uri         = "https://${local.region.principal}-run.googleapis.com/apis/run.googleapis.com/v1/namespaces/${local.project_id[terraform.workspace]}/jobs/restore-runner:run"

    oauth_token {
      service_account_email = module.sa-permissions.service_account_email
      scope                 = "https://www.googleapis.com/auth/cloud-platform"
    }
  }

  depends_on = [google_cloud_run_v2_job.restore_runner]
}

